import gurobipy as gp
from gurobipy import GRB

def main():
    model = gp.Model(env=env)

    I = [1, 2, 3]
    J = [1, 2, 3, 4, 5]

    c = {
        (1, 1): 4, (1, 2): 9, (1, 3): 2, (1, 4): 6, (1, 5): 5,
        (2, 1): 2, (2, 2): 6, (2, 3): 1, (2, 4): 7, (2, 5): 9,
        (3, 1): 2, (3, 2): 4, (3, 3): 9, (3, 4): 8, (3, 5): 3
    }

    s = {1: 60, 2: 30, 3: 45}
    d = {1: 15, 2: 35, 3: 20, 4: 5, 5: 40}

    x = model.addVars(I, J, lb=0, name="x")

    # Objective: minimize total transportation cost
    model.setObjective(
        gp.quicksum(c[i, j] * x[i, j] for i in I for j in J),
        GRB.MINIMIZE
    )

    # Supply (capacity) constraints
    for i in I:
        model.addConstr(
            gp.quicksum(x[i, j] for j in J) <= s[i],
            name=f"supply_{i}"
        )

    # Demand (balance) constraints
    for j in J:
        model.addConstr(
            gp.quicksum(x[i, j] for i in I) == d[j],
            name=f"demand_{j}"
        )

    model.optimize()

    if model.Status == GRB.OPTIMAL:
        print(f"FINAL_OBJECTIVE={model.ObjVal}")

if __name__ == "__main__":
