a = {'A':9,'B':27,'C':34,'D':40,'E':1,'F':31,'G':28,'H':20,'I':22}
w = {'A':7,'B':31,'C':31,'D':25,'E':29,'F':11,'G':28,'H':24,'I':20}
o = {'A':375,'B':419,'C':591,'D':510,'E':567,'F':64,'G':507,'H':377,'I':93}
c_p = {'A':8,'B':4,'C':5,'D':5,'E':2,'F':6,'G':8,'H':6,'I':8}
c_d = {'A':7,'B':7,'C':3,'D':4,'E':4,'F':7,'G':2,'H':4,'I':7}
B_len = 900
M_t = 96
M_s = 900

# Create model with runtime-provided environment
model = gp.Model(env=env)

# Decision variables
p = {}
s = {}
d = {}
for i in V:
    p[i] = model.addVar(vtype=GRB.INTEGER, lb=0, ub=B_len - L[i], name=f'p_{i}')
    s[i] = model.addVar(vtype=GRB.INTEGER, lb=a[i], name=f's_{i}')
    d[i] = model.addVar(vtype=GRB.INTEGER, lb=0, name=f'd_{i}')

# Time-ordering and space-ordering binaries for all ordered pairs
t = {}
x = {}
for i in V:
    for j in V:
        if i != j:
            t[(i,j)] = model.addVar(vtype=GRB.BINARY, name=f't_{i}_{j}')
            x[(i,j)] = model.addVar(vtype=GRB.BINARY, name=f'x_{i}_{j}')

model.update()

# Constraints

# 1. Berth length feasibility
for i in V:
    model.addConstr(p[i] + L[i] <= B_len, name=f'len_{i}')

# 2. Absolute deviation definition
for i in V:
    model.addConstr(d[i] >= p[i] - o[i], name=f'def1_{i}')
    model.addConstr(d[i] >= o[i] - p[i], name=f'def2_{i}')

# 3. Time-ordering consistency
for i in V:
    for j in V:
        if i < j:
            model.addConstr(t[(i,j)] + t[(j,i)] == 1, name=f'tcons_{i}_{j}')

# 4. Space-ordering consistency
for i in V:
    for j in V:
        if i < j:
            model.addConstr(x[(i,j)] + x[(j,i)] == 1, name=f'xcons_{i}_{j}')

# 5. Non-overlap in time
for i in V:
    for j in V:
        if i < j:
            model.addConstr(s[i] + w[i] <= s[j] + M_t * (1 - t[(i,j)]), name=f'ttime1_{i}_{j}')
            model.addConstr(s[j] + w[j] <= s[i] + M_t * t[(i,j)], name=f'ttime2_{i}_{j}')

# 6. Non-overlap in space when times overlap
for i in V:
    for j in V:
        if i < j:
            model.addConstr(p[i] + L[i] <= p[j] + M_s * (1 - x[(i,j)]) + M_s * (t[(i,j)] + t[(j,i)]), name=f'space1_{i}_{j}')
            model.addConstr(p[j] + L[j] <= p[i] + M_s * x[(i,j)] + M_s * (t[(i,j)] + t[(j,i)]), name=f'space2_{i}_{j}')

# Objective
obj = gp.quicksum(c_p[i] * d[i] + c_d[i] * (s[i] - a[i]) for i in V)
model.setObjective(obj, GRB.MINIMIZE)

# Optimize
model.optimize()

# Report final objective if optimal
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
