import math
import gurobipy as gp
from gurobipy import GRB

# Environment
env = gp.Env()
model = gp.Model(env=env)

# Sets
V = [0] + list(range(1, 13))          # 0 is depot, 1..12 are customers
N = list(range(1, 13))
K = [1, 2, 3, 4, 5]

# Parameters
coords = {
    0: (0.0, 0.0),
    1: (4.36, -2.75),
    2: (-7.29, -3.22),
    3: (-8.74, -2.47),
    4: (-0.68, -5.15),
    5: (-0.39, -3.49),
    6: (-6.06, -5.52),
    7: (-2.67, 9.32),
    8: (9.91, 7.87),
    9: (2.03, -2.98),
    10: (2.33, -1.47),
    11: (5.10, -2.08),
    12: (-8.04, -9.78)
}

demand = {
    1: 6, 2: 7, 3: 1, 4: 10, 5: 8,
    6: 7, 7: 3, 8: 6, 9: 5, 10: 2,
    11: 4, 12: 4
}

Q = 15
M = Q

# Distance matrix
c = {}
for i in V:
    c[i] = {}
    xi, yi = coords[i]
    for j in V:
        if i == j:
            c[i][j] = 0.0
        else:
            xj, yj = coords[j]
            c[i][j] = math.hypot(xi - xj, yi - yj)

# Decision variables
x = {}
for k in K:
    for i in V:
        for j in V:
            if i != j:
                x[i, j, k] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}_{k}")

z = {}
for k in K:
    z[k] = model.addVar(vtype=GRB.BINARY, name=f"z_{k}")

l = {}
for k in K:
    for i in V:
        l[i, k] = model.addVar(vtype=GRB.CONTINUOUS, lb=0.0, ub=Q, name=f"l_{i}_{k}")

u = {}
for k in K:
    for i in N:
        u[i, k] = model.addVar(vtype=GRB.INTEGER, lb=1, ub=len(N), name=f"u_{i}_{k}")

# Fix depot load and position
for k in K:
    model.addConstr(l[0, k] == 0.0, name=f"load_depot_{k}")
    model.addConstr(u[0, k] == 0, name=f"pos_depot_{k}")

# Objective
obj = gp.quicksum(c[i][j] * x[i, j, k] for k in K for i in V for j in V if i != j)
model.setObjective(obj, GRB.MINIMIZE)

# Constraints

# 1. Customer visit
for j in N:
    model.addConstr(
        gp.quicksum(x[i, j, k] for k in K for i in V if i != j) == 1,
        name=f"visit_{j}"
    )

# 2. Flow conservation
for k in K:
    for i in N:
        model.addConstr(
            gp.quicksum(x[i, j, k] for j in V if j != i) -
            gp.quicksum(x[j, i, k] for j in V if j != i) == 0,
            name=f"flow_{i}_{k}"
        )

# 3. Depot departure and return
for k in K:
    model.addConstr(
        gp.quicksum(x[0, j, k] for j in N) == z[k],
        name=f"depot_out_{k}"
    )
    model.addConstr(
        gp.quicksum(x[i, 0, k] for i in N) == z[k],
        name=f"depot_in_{k}"
    )

# 4. Load continuity
for k in K:
    for i in N:
        for j in V:
            if i != j:
                model.addConstr(
                    l[i, k] <= l[j, k] + demand[i] + M * (1 - x[j, i, k]),
                    name=f"load_up_{i}_{j}_{k}"
                )
                model.addConstr(
                    l[i, k] >= l[j, k] + demand[i] - M * (1 - x[j, i, k]),
                    name=f"load_down_{i}_{j}_{k}"
                )

# 5. Load bounds already set by variable bounds

# 6. Subtour elimination (MTZ)
for k in K:
    for i in N:
        for j in N:
            if i != j:
                model.addConstr(
                    u[i, k] - u[j, k] + len(N) * x[i, j, k] <= len(N) - 1,
                    name=f"mtz_{i}_{j}_{k}"
                )

# 7. Truck usage limit
model.addConstr(
    gp.quicksum(z[k] for k in K) <= len(K),
    name="truck_limit"
)

# Optimize
model.optimize()

# Output
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
```

