import gurobipy as gp
from gurobipy import GRB

def main(env):
    # Sets
    N = list(range(11))          # 0..10
    C = list(range(1, 11))       # 1..10

    # Coordinates
    x_coord = [0.0, -5.87, -4.10, -2.27, 4.36, 9.05, -7.46, 7.75, 0.06, -6.13, 3.25]
    y_coord = [0.0, -3.30, 4.60, -7.45, 3.38, 5.02, 6.97, 7.38, -4.25, -9.78, 9.86]

    # Time windows
    a = {i: None for i in C}
    b = {i: None for i in C}
    a[1], b[1] = 8, 12
    a[2], b[2] = 9, 13
    a[3], b[3] = 10, 15
    a[4], b[4] = 11, 15
    a[5], b[5] = 9, 16
    a[6], b[6] = 9, 17
    a[7], b[7] = 10, 18
    a[8], b[8] = 13, 19
    a[9], b[9] = 8, 16
    a[10], b[10] = 8, 16

    # Parameters
    v = 15.0          # speed km/h
    M = 1000.0        # big M
    n = 10            # number of communities

    # Distances and travel times
    d = {}
    tau = {}
    for i in N:
        for j in N:
            if i != j:
                dx = x_coord[i] - x_coord[j]
                dy = y_coord[i] - y_coord[j]
                dist = math.hypot(dx, dy)
                d[(i, j)] = dist
                tau[(i, j)] = dist / v

    # Model
    model = gp.Model(env=env)

    # Decision variables
    x = {}
    for i in N:
        for j in N:
            if i != j:
                x[(i, j)] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

    t = {}
    for i in N:
        t[i] = model.addVar(vtype=GRB.CONTINUOUS, name=f"t_{i}")

    u = {}
    for i in C:
        u[i] = model.addVar(vtype=GRB.CONTINUOUS, name=f"u_{i}")

    model.update()

    # Objective: minimize total travel distance
    obj = gp.quicksum(d[(i, j)] * x[(i, j)] for i in N for j in N if i != j)
    model.setObjective(obj, GRB.MINIMIZE)

    # 1. Depot flow
    model.addConstr(gp.quicksum(x[(0, j)] for j in C) == 1, name="depot_out")
    model.addConstr(gp.quicksum(x[(i, 0)] for i in C) == 1, name="depot_in")

    # 2. Community flow
    for i in C:
        model.addConstr(gp.quicksum(x[(i, j)] for j in N if j != i) == 1, name=f"out_{i}")
        model.addConstr(gp.quicksum(x[(i, j)] for i in N if i != j) == 1, name=f"in_{i}")

    # 3. Time windows
    for i in C:
        model.addConstr(t[i] >= a[i], name=f"tw_low_{i}")
        model.addConstr(t[i] <= b[i], name=f"tw_up_{i}")

    # 4. Time propagation
    for i in N:
        for j in N:
            if i != j:
                model.addConstr(
                    t[j] >= t[i] + tau[(i, j)] - M * (1 - x[(i, j)]),
                    name=f"time_{i}_{j}"
                )

    # 5. Start time at depot
    model.addConstr(t[0] == 8.0, name="start_time")

    # 6. Subtour elimination (MTZ)
    for i in C:
        for j in C:
            if i != j:
                model.addConstr(
                    u[i] - u[j] + n * x[(i, j)] <= n - 1,
                    name=f"mtz_{i}_{j}"
                )
    for i in C:
        model.addConstr(u[i] >= 1, name=f"u_low_{i}")
        model.addConstr(u[i] <= n, name=f"u_up_{i}")

    # Optimize
    model.optimize()

    # Output
    if model.status == GRB.OPTIMAL:
        print(f"FINAL_OBJECTIVE={model.objVal}")

if __name__ == "__main__":
    main(gp.Env())

