    I0 = 150         # initial inventory (kg)

    s = {1: 30000, 2: 35000, 3: 40000, 4: 36000, 5: 38000, 6: 42000}
    p = {1: 32000, 2: 36000, 3: 38000, 4: 33000, 5: 39000, 6: 40000}

    # Decision variables
    sell = {}
    buy = {}
    I = {}
    for t in T:
        sell[t] = model.addVar(lb=0, name=f"sell_{t}")
        buy[t] = model.addVar(lb=0, name=f"buy_{t}")
        I[t] = model.addVar(lb=0, name=f"I_{t}")

    # Inventory balance constraints
    for t in T:
        if t == 1:
            model.addConstr(I[t] == I0 - sell[t] + buy[t], name=f"inv_bal_{t}")
        else:
            model.addConstr(I[t] == I[t-1] - sell[t] + buy[t], name=f"inv_bal_{t}")

    # Capacity constraints
    for t in T:
        model.addConstr(I[t] <= C, name=f"cap_{t}")

    # Non‑negative inventory before selling
    for t in T:
        if t == 1:
            model.addConstr(I0 - sell[t] >= 0, name=f"pre_sell_{t}")
        else:
            model.addConstr(I[t-1] - sell[t] >= 0, name=f"pre_sell_{t}")

