import gurobipy as gp
from gurobipy import GRB

# Sets
G = [1, 2, 3, 4]          # worker rotation groups
Q = [1, 2, 3, 4]          # quarters
P = ['A', 'B']            # products

# Parameters
D = {
    'A': {1: 800, 2: 600, 3: 700, 4: 900},
    'B': {1: 500, 2: 400, 3: 600, 4: 300}
}
cap = {'A': 60, 'B': 40}
wage = 1800
h = 70

# Working‑quarter indicator
w_indicator = {(g, q): 0 if q == g else 1 for g in G for q in Q}

# Create model with provided environment
env = gp.Env()
m = gp.Model(env=env)
m.setParam('OutputFlag', 0)  # suppress Gurobi output

# Decision variables
W = {g: m.addVar(vtype=GRB.INTEGER, lb=0, name=f"W_{g}") for g in G}
x = {(g, q, p): m.addVar(vtype=GRB.INTEGER, lb=0, name=f"x_{g}_{q}_{p}")
     for g in G for q in Q for p in P}
I = {(p, q): m.addVar(vtype=GRB.CONTINUOUS, lb=0, name=f"I_{p}_{q}")
     for p in P for q in Q}

# Objective: minimize total annual operating cost
obj = gp.quicksum(wage * W[g] for g in G) + gp.quicksum(h * I[(p, q)] for p in P for q in Q)
m.setObjective(obj, GRB.MINIMIZE)

# Constraints

# 1. Worker assignment capacity
for g in G:
    for q in Q:
        m.addConstr(x[(g, q, 'A')] + x[(g, q, 'B')] <= W[g] * w_indicator[(g, q)],
                    name=f"cap_{g}_{q}")

# 2. Inventory balance
for p in P:
    for q in Q:
        prod = gp.quicksum(cap[p] * x[(g, q, p)] for g in G)
        if q == 1:
            m.addConstr(I[(p, q)] == prod - D[p][q], name=f"inv_{p}_{q}")
        else:
            m.addConstr(I[(p, q)] == I[(p, q - 1)] + prod - D[p][q],
                        name=f"inv_{p}_{q}")

# 4. Final inventory zero
for p in P:
    m.addConstr(I[(p, 4)] == 0, name=f"final_{p}")

# Optimize
m.optimize()

# Report optimal objective if found
if m.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={m.objVal}")

