from gurobipy import GRB

# Create environment and model
env = gp.Env()
model = gp.Model(env=env)

# Sets
T = [1, 2, 3, 4]
D = [1, 2, 3, 4]

# Parameters
R = {1: 20000, 2: 25000, 3: 30000, 4: 35000}
E = {1: 15000, 2: 35000, 3: 22000, 4: 28000}
r = {1: 0.002, 2: 0.008, 3: 0.015, 4: 0.03}
M = {d: 1 + d * r[d] for d in D}
C0 = 50000

# Decision variables
x = {}
for t in T:
    for d in D:
        if t + d <= 5:
            x[t, d] = model.addVar(lb=0, name=f"x_{t}_{d}")

c = {}
for t in range(1, 6):
    c[t] = model.addVar(lb=0, name=f"c_{t}")

model.update()

# Constraint 1: Initial cash
model.addConstr(c[1] == C0, name="init_cash")

# Constraint 2: Cash flow (maturity of investments)
for t in range(2, 6):
    expr = gp.LinExpr()
    for s in range(1, t):
        d = t - s
        if d in D:
            expr += x[s, d] * M[d]
    model.addConstr(c[t] == expr, name=f"cash_flow_{t}")

# Constraint 3: Investment feasibility
for t in T:
    expr = gp.LinExpr()
    for d in D:
        if t + d <= 5:
            expr += x[t, d]
    model.addConstr(expr == c[t] + R[t] - E[t], name=f"invest_feas_{t}")

