import gurobipy as gp
from gurobipy import GRB
import math

# Sets
N = list(range(13))          # 0..12
customers = list(range(1, 13))  # 1..12
K = list(range(1, 6))        # 1..5

# Parameters
coords = [
    (0.0, 0.0),
    (4.36, -2.75),
    (-7.29, -3.22),
    (-8.74, -2.47),
    (-0.68, -5.15),
    (-0.39, -3.49),
    (-6.06, -5.52),
    (-2.67, 9.32),
    (9.91, 7.87),
    (2.03, -2.98),
    (2.33, -1.47),
    (5.10, -2.08),
    (-8.04, -9.78)
]

# Euclidean distances
d = [[0.0 for _ in N] for _ in N]
for i in N:
    xi, yi = coords[i]
    for j in N:
        if i != j:
            xj, yj = coords[j]
            d[i][j] = math.hypot(xi - xj, yi - yj)

# Demands
dem = [0, 6, 7, 1, 10, 8, 7, 3, 6, 5, 2, 4, 4]

# Capacity
cap = 15

# Model
model = gp.Model(env=env)

# Decision variables
x = {}
for k in K:
    for i in N:
        for j in N:
            if i != j:
                x[(i, j, k)] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}_{k}")

y = {}
for k in K:
    for i in customers:
        y[(i, k)] = model.addVar(vtype=GRB.BINARY, name=f"y_{i}_{k}")

u = {}
for k in K:
    for i in customers:
        u[(i, k)] = model.addVar(lb=1, ub=cap, vtype=GRB.CONTINUOUS, name=f"u_{i}_{k}")

# Objective
model.setObjective(
    gp.quicksum(d[i][j] * x[(i, j, k)] for k in K for i in N for j in N if i != j),
    GRB.MINIMIZE
)

# 1. Customer visitation
for i in customers:
    model.addConstr(
        gp.quicksum(y[(i, k)] for k in K) == 1,
        name=f"visit_{i}"
    )

# 2. Truck flow conservation
for k in K:
    # Departure from depot
    model.addConstr(
        gp.quicksum(x[(0, j, k)] for j in customers) == gp.quicksum(y[(i, k)] for i in customers),
        name=f"dep_{k}"
    )
    # Return to depot
    model.addConstr(
        gp.quicksum(x[(i, 0, k)] for i in customers) == gp.quicksum(y[(i, k)] for i in customers),
        name=f"ret_{k}"
    )
    # Departure from customer
    for i in customers:
        model.addConstr(
            gp.quicksum(x[(i, j, k)] for j in N if j != i) == y[(i, k)],
            name=f"dep_cust_{i}_{k}"
        )
    # Arrival at customer
    for i in customers:
        model.addConstr(
            gp.quicksum(x[(j, i, k)] for j in N if j != i) == y[(i, k)],
            name=f"arr_cust_{i}_{k}"
        )

# 3. Truck capacity
for k in K:
    model.addConstr(
        gp.quicksum(dem[i] * y[(i, k)] for i in customers) <= cap,
        name=f"cap_{k}"
    )

# 4. Subtour elimination (MTZ)
for k in K:
    for i in customers:
        for j in customers:
            if i != j:
                model.addConstr(
                    u[(i, k)] - u[(j, k)] + cap * x[(i, j, k)] <= cap - 1,
                    name=f"mtz_{i}_{j}_{k}"
                )

# Optimize
model.optimize()

# Output
if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
