from gurobipy import GRB

model = gp.Model(env=env)

# Sets
B = ['P', 'A']          # Breweries
H = ['S', 'T']          # Hubs
T_years = [1, 2, 3]     # Years

# Parameters
C0 = {'P': 200, 'A': 300}          # Initial capacity (thousand gallons)
U = {'S': 400, 'T': 400}           # Hub handling capacity (thousand gallons)
p = {('P', 'S'): 500, ('P', 'T'): 450,
     ('A', 'S'): 480, ('A', 'T'): 520}  # Profit per thousand gallons
e = {'P': 1000, 'A': 1500}          # Expansion cost per thousand gallons

# Decision variables
x = {}
for b in B:
    x[b] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=f"x_{b}")

prod = {}
for b in B:
    for t in T_years:
        prod[(b, t)] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=f"prod_{b}_{t}")

ship = {}
for b in B:
    for h in H:
        for t in T_years:
            ship[(b, h, t)] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=f"ship_{b}_{h}_{t}")

# Constraints
# 1. Production equals shipments
for t in T_years:
    for b in B:
        model.addConstr(
            sum(ship[(b, h, t)] for h in H) == prod[(b, t)],
            name=f"prod_ship_{b}_{t}"
        )

# 2. Production limited by initial capacity plus expansion
for t in T_years:
    for b in B:
        model.addConstr(
            prod[(b, t)] <= C0[b] + x[b],
            name=f"cap_{b}_{t}"
        )

# 3. Hub handling capacity each year
for t in T_years:
    for h in H:
        model.addConstr(
            sum(ship[(b, h, t)] for b in B) <= U[h],
            name=f"hub_{h}_{t}"
        )

# Objective
obj = gp.quicksum(p[(b, h)] * ship[(b, h, t)] for t in T_years for b in B for h in H) - \
      gp.quicksum(e[b] * x[b] for b in B)
model.setObjective(obj, GRB.MAXIMIZE)

# Optimize
model.optimize()

# Report
if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
