    model.addConstr(gp.quicksum(L[c][h] * y[c] for c in cities) <= ln_0_10 - epsilon,
                    name=f"reliability_{h}")

model.setObjective(gp.quicksum(cost[c] * y[c] for c in cities), GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")

